using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class GaugeFeedProbe {
static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,null);}
static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
static double D(IntPtr p,int o){byte[] b=new byte[8];Marshal.Copy(IntPtr.Add(p,o),b,0,8);return BitConverter.ToDouble(b,0);}
[STAThread]static int Main(){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);var csv=new System.Text.StringBuilder("cycle,model_pm,arrow_pm,model_tm,arrow_tm\n");try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var cars=(IntPtr[])typeof(TrainerIntegrationHost).GetField("cars",flags).GetValue(h);var wrap=Marshal.ReadIntPtr(mem["CommOwner"],0x2bc);var form=Marshal.ReadIntPtr(wrap,0xc);var gauge=Marshal.ReadIntPtr(form,0x398);var pm=Marshal.ReadIntPtr(gauge,0x214);var tm=Marshal.ReadIntPtr(gauge,0x1f8);if(pm==IntPtr.Zero||tm==IntPtr.Zero)throw new Exception("Gauge pointer absent");double first=0,last=0,maxError=0;for(int n=0;n<900;n++){if(n==100)foreach(var car in cars)Marshal.Copy(BitConverter.GetBytes(4.5f),0,car,4);float beforePm=F(mem["TLocParam"],5),beforeTm=F(cars[0],0);Call(h,"ElectricalCycle");double p=D(pm,0x28),t=D(tm,0x28);if(n==0)first=p;last=p;double err=Math.Max(Math.Abs(beforePm-p),Math.Abs(beforeTm-t));maxError=Math.Max(maxError,err);if(err>0.03)throw new Exception("Gauge state differs from model cycle="+n+" error="+err);if(n%10==0)csv.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,"{0},{1:R},{2:R},{3:R},{4:R}\n",n,beforePm,p,beforeTm,t);Call(h,"ApplyTestInputs");Call(h,"PneumaticCycle");}if(Math.Abs(first-last)<.15)throw new Exception("Gauge pressure failed to change");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Trainer_gauge_feed_validation.json"),new JavaScriptSerializer().Serialize(new{passed=true,cycles=900,max_error_bar=maxError,first_pm_bar=first,last_pm_bar=last,scope="Native gauge object pressure values; rendered pixels not captured",rendered_pixels_verified=false}));Console.WriteLine("PASS gauge feed; first="+first+" last="+last+" maxError="+maxError);return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Trainer_gauge_feed_validation.csv"),csv.ToString());h.Close();h.Dispose();}}
}
